package com.didichuxing.doraemonkit.kit.network;

import java.net.URI;

/** Generated by client-adapters/dokit. Configure once when building your internal SDK. */
public final class DoKitBackendConfig {
    private DoKitBackendConfig() {}
    public static volatile String PLATFORM_BASE_URL = "https://dokit.example.internal";
    public static volatile String MOCK_BASE_URL = "https://dokit.example.internal";
    public static volatile String RESOURCE_BASE_URL = "https://dokit.example.internal/resources";
    public static volatile String HYBRID_JS_URL = "https://dokit.example.internal/resources/dokit.js";
    public static volatile String WEB_SOCKET_URL = "wss://dokit.example.internal/ws";
    public static volatile String SDK_TOKEN = "";
    public static final long DEFAULT_QUERY_TIMEOUT_MS = 8000L;
    public static volatile long QUERY_TIMEOUT_MS = DEFAULT_QUERY_TIMEOUT_MS;
    public static volatile String PROJECT_ID = "";
    public static volatile String VCONSOLE_URL = "https://dokit.example.internal/resources/vconsole.min.js";
    /**
     * Configure before DoKit.Builder.build(); restart the process to change servers/projects.
     * All fields are optional: null/blank strings disable that setting, and a null timeout uses 8000 ms.
     * Fields left unassigned retain the current configuration.
     */
    public static final class Options {
        public String platformBaseUrl = PLATFORM_BASE_URL;
        public String mockBaseUrl = MOCK_BASE_URL;
        public String resourceBaseUrl = RESOURCE_BASE_URL;
        public String hybridJsUrl = HYBRID_JS_URL;
        public String vConsoleUrl = VCONSOLE_URL;
        public String webSocketUrl = WEB_SOCKET_URL;
        public String projectId = PROJECT_ID;
        public String sdkToken = SDK_TOKEN;
        public Long queryTimeoutMs = QUERY_TIMEOUT_MS;
    }
    private static boolean locked;
    public static synchronized void lock() { locked = true; }
    public static synchronized void configure(Options options) {
        if (locked) throw new IllegalStateException("Configure DoKit before installation; restart to change backend");
        String platform = validateUrl(options.platformBaseUrl, false);
        String mock = validateUrl(options.mockBaseUrl, false);
        String resources = validateUrl(options.resourceBaseUrl, false);
        String hybrid = validateUrl(options.hybridJsUrl, false);
        String console = validateUrl(options.vConsoleUrl, false);
        String socket = validateUrl(options.webSocketUrl, true);
        String token = emptyIfBlank(options.sdkToken);
        String project = emptyIfBlank(options.projectId);
        long timeout = options.queryTimeoutMs == null ? DEFAULT_QUERY_TIMEOUT_MS : options.queryTimeoutMs;
        if (!token.matches("[A-Za-z0-9._~+/=:-]*") || timeout < 100 || timeout > 60000)
            throw new IllegalArgumentException("Invalid DoKit token or timeout");
        PLATFORM_BASE_URL = platform;
        MOCK_BASE_URL = mock;
        RESOURCE_BASE_URL = resources;
        HYBRID_JS_URL = hybrid;
        VCONSOLE_URL = console;
        WEB_SOCKET_URL = socket;
        PROJECT_ID = project;
        SDK_TOKEN = token;
        QUERY_TIMEOUT_MS = timeout;
    }
    private static String emptyIfBlank(String value) {
        return value == null || value.trim().isEmpty() ? "" : value;
    }
    private static String validateUrl(String value, boolean socket) {
        value = emptyIfBlank(value);
        if (value.isEmpty()) return "";
        if (value.matches(".*[\\s\\\\<>\"'].*")) throw new IllegalArgumentException("Invalid DoKit URL");
        URI uri = URI.create(value);
        String scheme = uri.getScheme();
        if (!(socket ? ("ws".equalsIgnoreCase(scheme) || "wss".equalsIgnoreCase(scheme)) :
                ("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))) ||
                uri.getHost() == null || uri.getUserInfo() != null || uri.getFragment() != null ||
                (!socket && uri.getQuery() != null) || uri.getPort() == 0 || uri.getPort() > 65535)
            throw new IllegalArgumentException("Invalid DoKit URL");
        return value.replaceAll("/+$", "");
    }

    public static String host(String base) {
        if (emptyIfBlank(base).isEmpty()) return "";
        try {
            String host = URI.create(base).getHost();
            return host == null ? "" : host;
        } catch (IllegalArgumentException ignored) { return ""; }
    }
    public static String endpoint(String base, String path) {
        return emptyIfBlank(base).isEmpty() ? "" : base + path;
    }
    public static boolean isPlatformUrl(String url) {
        if (emptyIfBlank(url).isEmpty()) return false;
        try {
            URI target = URI.create(url);
            for (String base : new String[] {PLATFORM_BASE_URL, MOCK_BASE_URL, RESOURCE_BASE_URL}) {
                if (emptyIfBlank(base).isEmpty()) continue;
                URI own = URI.create(base);
                int ownPort = own.getPort() < 0 ? ("https".equals(own.getScheme()) ? 443 : 80) : own.getPort();
                int port = target.getPort() < 0 ? ("https".equals(target.getScheme()) ? 443 : 80) : target.getPort();
                String prefix = own.getPath() == null ? "" : own.getPath();
                String path = target.getPath() == null ? "/" : target.getPath();
                if (own.getScheme().equalsIgnoreCase(target.getScheme()) &&
                    own.getHost().equalsIgnoreCase(target.getHost()) && ownPort == port &&
                    (prefix.isEmpty() || path.equals(prefix) || path.startsWith(prefix + "/"))) return true;
            }
        } catch (IllegalArgumentException ignored) {}
        return false;
    }
}
